-- Sample data for the Oxro Labs workspace. Run in the Supabase SQL editor AFTER you have signed up and created the workspace.
-- Safe to re-run: it does nothing if the workspace already has transactions. Dates are relative to today.
-- (GENERATED by scripts/_gen_seed.mjs — GSTINs carry valid checksums.)
do $$
declare v_org uuid; v_user uuid;
begin
  select m.org_id, m.user_id into v_org, v_user
  from public.org_members m where m.role = 'admin' order by m.created_at limit 1;
  if v_org is null then raise exception 'No workspace found. Sign in to the app and create the workspace first.'; end if;
  if exists (select 1 from public.entries where org_id = v_org) then raise notice 'Workspace already has data; seed skipped.'; return; end if;

  -- the approval trigger consults auth.uid(), which is null in the SQL editor; seeded rows are pre-approved
  alter table public.entries disable trigger entries_approval_guard;

  update public.orgs set gstin = '27AABCF1234F1Z4', opening_balance = 150000, monthly_goal = 100000 where id = v_org;





  -- a 3-day check-in streak and a first XP balance for the admin
  on conflict do nothing;

  alter table public.entries enable trigger entries_approval_guard;
  raise notice 'Seeded % parties, % entries, 1 recurring template, 2 filings.', 5, 14;
end $$;
